import{_ as a,C as r,c as s,o as i,a3 as o,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Create a quotation from an opportunity","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/create-quotation.md","filePath":"master/sales/crm/pipeline/create-quotation.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/pipeline/create-quotation.md"};function u(h,t,d,p,m,g){const e=r("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=o('<h1 id="create-a-quotation-from-an-opportunity" tabindex="-1">Create a quotation from an opportunity <a class="header-anchor" href="#create-a-quotation-from-an-opportunity" aria-label="Permalink to &quot;Create a quotation from an opportunity&quot;">​</a></h1><p>A quotation is an offer with products and prices. You can start one straight from an opportunity, so the offer stays linked to the deal. The quotation itself is a Sales document, with its own form and steps.</p><blockquote><p><strong>In simple words:</strong> Click <strong>New Quotation</strong> on the opportunity to send the customer an offer. The quotation remembers which deal it came from.</p></blockquote><h2 id="create-a-quotation" tabindex="-1">Create a quotation <a class="header-anchor" href="#create-a-quotation" aria-label="Permalink to &quot;Create a quotation&quot;">​</a></h2><p>Example: you offer Sharma Textiles the annual licence.</p><ol><li>Open <strong>Annual ERP licence - Sharma Textiles</strong> from <code>CRM → Sales → My Pipeline</code>.</li><li>Click <strong>New Quotation</strong>.</li></ol>',6)),n(e,{src:"/images1/crm/opportunity-new-quotation.png",alt:"Opportunity page header with the New Quotation button highlighted among the action buttons"}),t[1]||(t[1]=o('<ol start="3"><li>If the opportunity already has a customer, the quotation form opens at once. Skip to step 6.</li><li>If it has no customer, the dialog <strong>New quotation</strong> opens. It says the opportunity has no customer yet.</li></ol><ol start="5"><li>Fill in the dialog.</li></ol><ul><li><strong><em>Customer:</em></strong> Required. Choose one option. <ul><li><strong>Create a new customer:</strong> makes a customer from the contact details on the opportunity.</li><li><strong>Link to an existing customer:</strong> attaches a customer you already have.</li><li><strong>Do not link to a customer:</strong> continues without one.</li></ul></li><li><strong><em>Existing customer:</em></strong> Search for the customer. Shown and required only for <strong>Link to an existing customer</strong>.</li></ul><p>Click <strong>Continue</strong>.</p><ol start="6"><li>The quotation form opens. The subheading reads <strong>From opportunity</strong> with the deal name.</li></ol>',5)),n(e,{src:"/images1/crm/quotation-from-opportunity.png",alt:"Create Quotation form opened from the opportunity, with the customer Sharma Textiles Pvt. Ltd. and the line From opportunity"}),t[2]||(t[2]=o('<ol start="7"><li>Add products, prices and terms, then save.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you cannot edit the opportunity, the dialog offers only <strong>Do not link to a customer</strong>.</p></div><h3 id="what-is-filled-in-for-you" tabindex="-1">What is filled in for you <a class="header-anchor" href="#what-is-filled-in-for-you" aria-label="Permalink to &quot;What is filled in for you&quot;">​</a></h3><p>The quotation takes these values from the opportunity.</p><ul><li><strong><em>Customer:</em></strong> The opportunity customer, if it has one.</li><li><strong><em>Salesperson:</em></strong> The opportunity salesperson.</li><li><strong><em>Company:</em></strong> The opportunity company.</li><li><strong><em>Origin:</em></strong> The opportunity name, so you can trace the offer back.</li><li><strong><em>Campaign, Medium and Source:</em></strong> The marketing details of the opportunity, when they are set.</li><li><strong><em>Sales Team:</em></strong> The opportunity team, when the quotation has no team of its own.</li></ul><p><strong>Example:</strong> The quotation for Sharma Textiles opens with Customer <code>Sharma Textiles</code>, Salesperson <code>ERP Admin</code> and Origin <code>Annual ERP licence - Sharma Textiles</code>.</p><p>The <strong>Payment Term</strong> is required on the Sales form. Pick one, for example <strong>Immediate Payment</strong>. You fill the rest on the Sales form. For every field, see <a href="./../../sales/quotations-orders/create-quotation.html">Create a quotation</a>.</p><h2 id="find-quotations" tabindex="-1">Find quotations <a class="header-anchor" href="#find-quotations" aria-label="Permalink to &quot;Find quotations&quot;">​</a></h2><h3 id="on-the-opportunity" tabindex="-1">On the opportunity <a class="header-anchor" href="#on-the-opportunity" aria-label="Permalink to &quot;On the opportunity&quot;">​</a></h3><p>Click the <strong>Quotations</strong> tab. A number badge shows how many quotations are not cancelled.</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Number</strong></td><td>The quotation reference.</td></tr><tr><td><strong>Date</strong></td><td>The order date.</td></tr><tr><td><strong>Customer</strong></td><td>Who the offer is for.</td></tr><tr><td><strong>Salesperson</strong></td><td>The person who owns it.</td></tr><tr><td><strong>Total</strong></td><td>The total amount.</td></tr><tr><td><strong>Status</strong></td><td>The state of the quotation.</td></tr></tbody></table><p>Click a row to open the quotation. The header also has <strong>New Quotation</strong>. With no quotations, the tab says <strong>No quotations yet</strong>.</p><p>The tab appears on opportunities only, not on leads.</p><h3 id="for-all-deals" tabindex="-1">For all deals <a class="header-anchor" href="#for-all-deals" aria-label="Permalink to &quot;For all deals&quot;">​</a></h3><p>Go to <code>CRM → Sales → My Quotations</code>. The page has <strong>List</strong>, <strong>Kanban</strong> and <strong>Graph</strong> layouts. The header has <strong>Export</strong> and <strong>New Quotation</strong>.</p>',15)),n(e,{src:"/images1/crm/my-quotations-list.png",alt:"My Quotations list with the Quotations tab open"}),t[3]||(t[3]=o('<ul><li><strong>Tabs.</strong> <strong>Default</strong>, <strong>My Quotations</strong>, <strong>Quotations</strong>, <strong>Sales Orders</strong> and <strong>Archived</strong>.</li><li><strong>Columns.</strong> <strong>Number</strong>, <strong>Creation date</strong>, <strong>Customer</strong>, <strong>Sales person</strong>, <strong>Amount total</strong> and <strong>Status</strong>.</li><li><strong>Group by.</strong> Medium, Source, Team, Sales Person, Currency, Company, Customer, Quotation Date, Commitment Date and Status.</li><li><strong>Kanban.</strong> Cards sit in columns by status. Each card shows the customer, total, date and salesperson.</li><li><strong>Bulk actions.</strong> <strong>Send email</strong>, <strong>Mark Quotation as Sent</strong>, <strong>Confirm</strong>, <strong>Export</strong>, <strong>Restore</strong>, <strong>Delete</strong> and <strong>Force delete</strong>.</li></ul><p>On the quotation, an <strong>Opportunity</strong> tab opens the linked deal. You can win or lose it from there.</p><h2 id="after-the-quotation" tabindex="-1">After the quotation <a class="header-anchor" href="#after-the-quotation" aria-label="Permalink to &quot;After the quotation&quot;">​</a></h2><p>Send the offer and confirm it when the customer agrees. See <a href="./../../sales/quotations-orders/send-and-confirm-quotation.html">Send and confirm a quotation</a>. Then mark the deal won. See <a href="./mark-won-lost.html">Mark an opportunity won or lost</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Link.</strong> The quotation stores the opportunity it came from. This link drives the <strong>Quotations</strong> tab.</li><li><strong>Customer choice.</strong> The choice in the dialog is kept with the quotation. A new or linked customer is saved on the opportunity too.</li><li><strong>Team cards.</strong> Draft and sent quotations count toward <strong>Quotations</strong> on the team card. See <a href="./manage-sales-teams.html">Manage sales teams</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../sales/quotations-orders/">Quotations and orders</a></li><li><a href="./manage-opportunities.html">Manage opportunities</a></li><li><a href="./mark-won-lost.html">Mark an opportunity won or lost</a></li></ul>',8))])}const q=a(l,[["render",u]]);export{f as __pageData,q as default};
